"""Session routes.

Every result is a status envelope that also carries the answers resolved so far, so a step
that still needs the user can fill the fields that are already known.
"""

import re
import time

from fastapi import APIRouter, Depends, HTTPException, Request, status as http_status

from .auth import Principal, require_user
from .config import Settings, get_settings
from .models import JobContext, SessionCreate, SessionView, StepRequest, StepResult
from .resolve import load_known, resolve
from .store import FirestoreStore, Store

# Firestore ids are generated by the server, but the path segment still has to be checked
# so a crafted id cannot address another collection.
_SESSION_ID = re.compile(r"^[A-Za-z0-9_-]{1,64}$")

router = APIRouter()


def get_store(request: Request) -> Store:
    store = getattr(request.app.state, "store", None)
    if store is None:
        store = FirestoreStore()
        request.app.state.store = store
    return store


def _job(session: dict) -> JobContext:
    return JobContext(
        url=str(session.get("url") or ""),
        company=str(session.get("company") or ""),
        role=str(session.get("role") or ""),
        jd_text=str(session.get("jd_text") or ""),
    )


def _session_or_404(store: Store, uid: str, session_id: str) -> dict:
    if not _SESSION_ID.match(session_id):
        raise HTTPException(http_status.HTTP_404_NOT_FOUND, "Session not found.")
    session = store.get_session(uid, session_id)
    if session is None:
        raise HTTPException(http_status.HTTP_404_NOT_FOUND, "Session not found.")
    return session


@router.get("/healthz")
def healthz(settings: Settings = Depends(get_settings)) -> dict:
    return {"ok": True, "version": settings.version, "appCheckRequired": settings.require_app_check}


@router.post("/v1/sessions", response_model=SessionView, status_code=http_status.HTTP_201_CREATED)
def create_session(
    body: SessionCreate,
    user: Principal = Depends(require_user),
    store: Store = Depends(get_store),
    settings: Settings = Depends(get_settings),
) -> SessionView:
    now = int(time.time())
    session_id = store.create_session(
        user.uid,
        {
            **body.model_dump(),
            "step": 1,
            "status": "created",
            "created_at": now,
            "updated_at": now,
            "expires_at": now + settings.session_ttl_hours * 3600,
        },
    )
    return SessionView(session_id=session_id, step=1, status="created", job=body)


@router.post("/v1/sessions/{session_id}/step", response_model=StepResult)
def send_step(
    session_id: str,
    body: StepRequest,
    user: Principal = Depends(require_user),
    store: Store = Depends(get_store),
) -> StepResult:
    session = _session_or_404(store, user.uid, session_id)
    company = str(session.get("company") or "")
    facts, memories = load_known(store, user.uid, body.fields, company)
    resolution = resolve(body.fields, facts, memories, company)
    result = StepResult(
        status=resolution.status,
        answers=resolution.answers,
        unresolved=resolution.unresolved,
        stats=resolution.stats(),
    )
    store.update_session(
        user.uid,
        session_id,
        {"step": body.step, "status": resolution.status, "updated_at": int(time.time()), "last_result": result.model_dump()},
    )
    return result


@router.get("/v1/sessions/{session_id}", response_model=SessionView)
def read_session(
    session_id: str,
    user: Principal = Depends(require_user),
    store: Store = Depends(get_store),
) -> SessionView:
    session = _session_or_404(store, user.uid, session_id)
    last_result = session.get("last_result")
    return SessionView(
        session_id=session_id,
        step=int(session.get("step") or 1),
        status=session.get("status") or "created",
        job=_job(session),
        last_result=StepResult.model_validate(last_result) if last_result else None,
    )
